-- 446: Original BrillaPrep WASSCE Core Mathematics sprint 2 beta questions, part 4 of 10 (batch wassce-core-math-sprint2-001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_446_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_446_guard;
INSERT INTO _migration_446_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_016' AND NOT (q.topic_id IS 'topic_wcoremath_trigonometry' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'From the top of a cliff 40 m high, the angle of depression of a boat at sea is 30°. Calculate the distance of the boat from the foot of the cliff, leaving your answer in surd form.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '40√3 m' AND q.explanation IS 'The angle of depression from the top equals the angle of elevation from the boat (alternate angles). In the right-angled triangle, tan 30° = 40/d, so d = 40 ÷ tan 30° = 40 ÷ (1/√3) = 40√3 m. Answer: the boat is 40√3 m from the foot of the cliff.' AND q.difficulty IS 'hard' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_016' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_446_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_017' AND NOT (q.topic_id IS 'topic_wcoremath_statistics' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The mean of five numbers is 8. Four of the numbers are 6, 9, 7 and 12. Find the fifth number.' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 6","B. 8","C. 8.5","D. 4"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The five numbers total 5 × 8 = 40. The four known numbers total 6 + 9 + 7 + 12 = 34, so the fifth number is 40 − 34 = 6. (8.5 is the mean of the four given numbers only.) Therefore the correct answer is A: 6.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_017' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_446_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_018' AND NOT (q.topic_id IS 'topic_wcoremath_statistics' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A fair die is thrown twice. What is the probability that the two scores add up to 9?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. 1/6","B. 1/9","C. 1/12","D. 5/36"]' AND q.correct_answer IS 'B' AND q.explanation IS 'There are 6 × 6 = 36 equally likely outcomes. The outcomes totalling 9 are (3, 6), (4, 5), (5, 4) and (6, 3) — four of them — so the probability is 4/36 = 1/9. Therefore the correct answer is B: 1/9.' AND q.difficulty IS 'hard' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_018' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_446_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_019' AND NOT (q.topic_id IS 'topic_wcoremath_statistics' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The marks of eight students in a test are 5, 6, 8, 8, 9, 10, 12 and 14. Calculate the mean mark.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '9' AND q.explanation IS 'The sum of the marks is 5 + 6 + 8 + 8 + 9 + 10 + 12 + 14 = 72. Dividing the total by the number of students gives the mean: 72 ÷ 8 = 9. Answer: the mean mark is 9.' AND q.difficulty IS 'medium' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Calculate' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_019' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_446_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_coremath_s2_020' AND NOT (q.topic_id IS 'topic_wcoremath_statistics' AND q.subject_id IS 'subj_wassce_core_math' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A box contains 3 green balls and 5 yellow balls. Two balls are picked at random, one after the other, without replacement. Find the probability that they are of different colours.' AND q.question_type IS 'calculation' AND q.round_type IS NULL AND q.options IS NULL AND q.correct_answer IS '15/28' AND q.explanation IS 'P(green then yellow) = (3/8) × (5/7) = 15/56, and P(yellow then green) = (5/8) × (3/7) = 15/56. The two cases are mutually exclusive, so add them: 15/56 + 15/56 = 30/56 = 15/28. Answer: 15/28.' AND q.difficulty IS 'hard' AND q.points IS '4' AND q.marks IS '2' AND q.time_limit IS '120' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Find' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_coremath_s2_020' AND NOT (r.batch_id IS 'wassce-core-math-sprint2-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Core Mathematics practice questions; not official WAEC (West African Examinations Council) examination material. Use the enabled feedback channel to report corrections.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_016', 'topic_wcoremath_trigonometry', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'From the top of a cliff 40 m high, the angle of depression of a boat at sea is 30°. Calculate the distance of the boat from the foot of the cliff, leaving your answer in surd form.', 'calculation', NULL, NULL, '40√3 m', 'The angle of depression from the top equals the angle of elevation from the boat (alternate angles). In the right-angled triangle, tan 30° = 40/d, so d = 40 ÷ tan 30° = 40 ÷ (1/√3) = 40√3 m. Answer: the boat is 40√3 m from the foot of the cliff.', 'hard', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_017', 'topic_wcoremath_statistics', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'The mean of five numbers is 8. Four of the numbers are 6, 9, 7 and 12. Find the fifth number.', 'multiple_choice', NULL, '["A. 6","B. 8","C. 8.5","D. 4"]', 'A', 'The five numbers total 5 × 8 = 40. The four known numbers total 6 + 9 + 7 + 12 = 34, so the fifth number is 40 − 34 = 6. (8.5 is the mean of the four given numbers only.) Therefore the correct answer is A: 6.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Find', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_018', 'topic_wcoremath_statistics', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'A fair die is thrown twice. What is the probability that the two scores add up to 9?', 'multiple_choice', NULL, '["A. 1/6","B. 1/9","C. 1/12","D. 5/36"]', 'B', 'There are 6 × 6 = 36 equally likely outcomes. The outcomes totalling 9 are (3, 6), (4, 5), (5, 4) and (6, 3) — four of them — so the probability is 4/36 = 1/9. Therefore the correct answer is B: 1/9.', 'hard', '1', '1', '90', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO3', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_019', 'topic_wcoremath_statistics', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'The marks of eight students in a test are 5, 6, 8, 8, 9, 10, 12 and 14. Calculate the mean mark.', 'calculation', NULL, NULL, '9', 'The sum of the marks is 5 + 6 + 8 + 8 + 9 + 10 + 12 + 14 = 72. Dividing the total by the number of students gives the mean: 72 ÷ 8 = 9. Answer: the mean mark is 9.', 'medium', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Calculate', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_coremath_s2_020', 'topic_wcoremath_statistics', 'subj_wassce_core_math', 'exam_wassce', NULL, NULL, 'A box contains 3 green balls and 5 yellow balls. Two balls are picked at random, one after the other, without replacement. Find the probability that they are of different colours.', 'calculation', NULL, NULL, '15/28', 'P(green then yellow) = (3/8) × (5/7) = 15/56, and P(yellow then green) = (5/8) × (3/7) = 15/56. The two cases are mutually exclusive, so add them: 15/56 + 15/56 = 30/56 = 15/28. Answer: 15/28.', 'hard', '4', '2', '120', NULL, NULL, '1', NULL, NULL, 'Find', 'AO3', NULL, NULL, 'board_waec');
